1	import React, { useRef, useState } from "react";
2	
3	/** Map a horizontal scroll position to a 0-based page index across 2 pages. */
4	export function pageFromScroll(scrollLeft: number, scrollWidth: number, clientWidth: number): 0 | 1 {
5	  const maxScroll = Math.max(0, scrollWidth - clientWidth);
6	  if (maxScroll === 0) return 0;
7	  return scrollLeft > maxScroll / 2 ? 1 : 0;
8	}
9	
10	const SKY = "#58ABFF";
11	const PILL_BG = "#E9E9E6"; // slightly darker off-white than the #F4F4F4 page bg (adjustable)
12	
13	export type StatPill = { label: string; v: number; Ico: React.ComponentType<{ c?: string }> };
14	
15	export function StatCarousel({ stats }: { stats: StatPill[] }) {
16	  const ref = useRef<HTMLDivElement>(null);
17	  const [page, setPage] = useState<0 | 1>(0);
18	
19	  const onScroll = () => {
20	    const el = ref.current;
21	    if (!el) return;
22	    setPage(pageFromScroll(el.scrollLeft, el.scrollWidth, el.clientWidth));
23	  };
24	
25	  return (
26	    <div style={{ padding: "16px 18px 0" }}>
27	      <div
28	        ref={ref}
29	        onScroll={onScroll}
30	        style={{
31	          display: "flex",
32	          gap: 12,
33	          overflowX: "auto",
34	          scrollSnapType: "x mandatory",
35	          WebkitOverflowScrolling: "touch",
36	          scrollbarWidth: "none",
37	        }}
38	      >
39	        {stats.map(({ label, v, Ico }) => (
40	          <div
41	            key={label}
42	            style={{
43	              flex: "0 0 calc(50% - 6px)", // 2 pills per view (gap 12 -> 6 each)
44	              scrollSnapAlign: "start",
45	              background: PILL_BG,
46	              borderRadius: 22,
47	              padding: "16px 16px",
48	              minHeight: 100,
49	              display: "flex",
50	              flexDirection: "column",
51	              justifyContent: "flex-start",
52	              boxSizing: "border-box",
53	            }}
54	          >
55	            <div style={{ marginBottom: 10 }}><Ico c={SKY} /></div>
56	            <div style={{ fontWeight: 700, fontSize: 9, color: SKY, letterSpacing: "0.06em", textTransform: "uppercase", marginBottom: 6, whiteSpace: "nowrap" }}>{label}</div>
57	            <div style={{ fontWeight: 800, fontSize: 30, color: SKY, letterSpacing: "-0.03em", lineHeight: 1, fontVariantNumeric: "tabular-nums" }}>{v}</div>
58	          </div>
59	        ))}
60	      </div>
61	
62	      {/* 2 page dots */}
63	      <div style={{ display: "flex", justifyContent: "center", gap: 7, marginTop: 12 }}>
64	        {[0, 1].map((i) => (
65	          <span
66	            key={i}
67	            style={{
68	              width: page === i ? 18 : 6,
69	              height: 6,
70	              borderRadius: 999,
71	              background: page === i ? SKY : "rgba(88,171,255,0.3)",
72	              transition: "width 0.3s cubic-bezier(0.34,1.56,0.64,1), background 0.3s ease",
73	            }}
74	          />
75	        ))}
76	      </div>
77	    </div>
78	  );
79	}
